func storeNumeric(val decimal.Decimal, intDigits, decDigits int) decimal.Decimal {
	// truncate toward zero to decDigits
	v := val.Truncate(int32(decDigits))
	// overflow: keep low-order digits
	totalDigits := intDigits + decDigits
	// scale
	pow10dec := decimal.New(1, int32(decDigits))
	pow10total := decimal.New(1, int32(totalDigits))
	scaled := v.Mul(pow10dec)
	// scaled is integer (maybe with exponent 0)
	// modulo
	mod := scaled.Mod(pow10total)
	// for negative, Mod in shopspring returns sign of dividend ? need adjust
	// shopspring Mod follows sign of dividend, so fine
	// convert back
	res := mod.Div(pow10dec)
	// ensure truncate to decDigits (already)
	return res.Truncate(int32(decDigits))
}

func storeInt(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low order digits, preserve sign? counts are positive
	if val < 0 {
		// for negative, keep sign and low digits
		abs := -val
		abs = abs % mod
		return -abs
	}
	return val % mod
}

