func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// s should be digits, maybe with sign? Assume positive
	// Remove any non-digit? Keep digits
	// Parse as integer
	// Use decimal.NewFromString with digits and scale
	// digits string may have leading zeros
	// Build integer value
	// Use decimal.NewFromString? But we need integer then shift
	// Use decimal.RequireFromString for digits then shift
	// Actually digits represent integer with implied decimal
	// e.g., "0010000" with scale 2 => 100.00 => decimal.New(10000, -2)
	// parse digits as int64
	// Could exceed int64 for large, but max 11 digits fits
	var neg bool
	if len(s) > 0 && s[0] == '-' {
		neg = true
		s = s[1:]
	} else if len(s) > 0 && s[0] == '+' {
		s = s[1:]
	}
	// filter digits
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(digits)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

