			deptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	payPara()
	readPara()
}

func payPara() {
	forty := decimal.NewFromInt(40)
	if empRec.ErHours.GreaterThan(forty) {
		WsRegHours = storeNumeric(decimal.NewFromInt(40), 3, 1)
		WsOtHours = storeNumeric(empRec.ErHours.Sub(forty), 3, 1)
	} else {
		WsRegHours = storeNumeric(empRec.ErHours, 3, 1)
		WsOtHours = storeNumeric(decimal.Zero, 3, 1)
	}
	onePointFive := decimal.New(15, -1)
	computed := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(onePointFive))
	rounded := computed.Round(2)
	WsGross = storeNumeric(rounded, 7, 2)

	WsDeptTotal = storeNumeric(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	WsGrandTotal = storeNumeric(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = storeInt(WsGrandCount+1, 5)

	WsHoursEd = formatEditedWrapper(empRec.ErHours, "ZZ9.9")
	WsRateEd = formatEditedWrapper(empRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEditedWrapper(WsGross, "Z,ZZZ,ZZ9.99")
	// DISPLAY
	fmt.Printf("%s %s %s %s %s\n", empRec.ErId, empRec.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func deptBreakPara() {
	WsDeptEd = formatEditedWrapper(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsDeptCount%1000)
	// handle overflow negative? not needed
	// For general, ensure modulo
	if WsDeptCount < 0 {
		// shouldn't happen
		countStr = fmt.Sprintf("%03d", storeInt(WsDeptCount, 3))
	}
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func grandPara() {
	WsGrandEd = formatEditedWrapper(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsGrandCount%100000)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func mainPara() {
	// OPEN INPUT
	// read file input.dat
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if file not found, treat as empty
		fileLines = []string{}
	} else {
		// split line sequential
		// Use bufio scanner to preserve? Use manual split on \n
		content := string(data)
		// Normalize \r\n
		content = strings.ReplaceAll(content, "\r\n", "\n")
		content = strings.ReplaceAll(content, "\r", "\n")
		if content == "" {
			fileLines = []string{}
		} else {
			lines := strings.Split(content, "\n")
			// If file ends with newline, last element is "" should be ignored? COBOL LINE SEQUENTIAL: final newline does not create extra record.
			// So if last element is empty due to trailing newline, drop it
			if len(lines) > 0 && lines[len(lines)-1] == "" {
				lines = lines[:len(lines)-1]
			}
			fileLines = lines
		}
	}
	fileIdx = 0

	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	if WsFirstFlag != "Y" {
		deptBreakPara()
	}
	// CLOSE
	grandPara()

	// ensure unused import bufio is used
	_ = bufio.NewReader(nil)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.Zero
	WsOtHours = decimal.Zero
	WsGross = decimal.Zero
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
	WsGrandTotal = decimal.Zero
	WsGrandCount = 0

	mainPara()
}

